cd "$(dirname "$0")/.."

sb() { npx -y supabase@latest "$@"; }

# sql "query" runs one query on the live database and prints only its rows' values.
sql() { sb db query --remote="$REF" --yes "$1" 2>/dev/null | grep -oE '"[a-z_]+": [^,}]+' || true; }

# vault_url NAME FUNCTION adds the Vault URL that switches a sync job on, once.
vault_url() {
  sb db query --remote="$REF" --yes "select vault.create_secret('$URL/functions/v1/$2', '$1')
    where not exists (select 1 from vault.secrets where name = '$1')" >/dev/null 2>&1 \
    && printf '  %s✓ switched on%s %s (Vault %s)\n' "$GREEN" "$RESET" "$2" "$1" \
    || { SKIPPED+=("Vault URL $1 (docs/sheet-v5.md, Deploy step 7)"); warn "couldn't add $1; try again later"; }
}

# What's already set up, read once at the start (names and counts only, never a secret's value),
# so the wizard shows only the steps left. Re-run it any time: finished steps stay hidden.
SECRET_NAMES=""; STATE=""
load_state() {
  # The Supabase CLI must be logged in (to the account that owns the-sheet) for every check and
  # Vault step below; without it the wizard would silently see nothing.
  note "· Supabase login (if this sits here, look for a macOS Keychain prompt and click Always Allow)"
  if ! sb secrets list --project-ref "$REF" >/dev/null 2>&1; then
    warn "The Supabase CLI isn't logged in here (or not to the account that owns the-sheet)."
    say "Run this once, sign in in the browser it opens, then run this wizard again:"
    say "    npx -y supabase@latest login"
    exit 1
  fi
  note "· function secrets (names only)"
  SECRET_NAMES=$(sb secrets list --project-ref "$REF" 2>/dev/null | grep -oE '"name":"[A-Z0-9_]+"' | cut -d'"' -f4 | tr '\n' ' ' || true)
  note "· the database (calendar, Oura, GitHub orgs, replans, habits, sync switches)"
  STATE=$(sql "select
    (select count(*) from calendar_account) as cal,
    (select count(*) from oura_account) as oura,
    (select coalesce(array_length(github_orgs, 1), 0) from settings) as orgs,
    (select replans_on from settings) as replans,
    (select count(*) from habits) as habits,
    (select string_agg(name, ' ') from vault.secrets where name like 'sheet_%_url') as vault")
}
has_secret() { [[ " $SECRET_NAMES " == *" $1 "* ]]; }
in_vault() { [[ "$STATE" == *"$1"* ]]; }
state_is() { grep -qE "\"$1\": *\"?$2" <<<"$STATE"; }
